attrs.model_info:
An ensemble of 36 neural networks was used (tensorflow). All neural networks 
have the following properties and training options:
batch_size = 2048;
learning_rate = 0.005;
loss = rmse;
layers = [Normalisation, Dense64, Dense32, Dense1];

attrs.model_predictors:
xco2_anom = Mauna Loa xCO2 weekly anom since 19XX; 
sst_anom = sst - sst_clim; 
sss_anom = sss - sss_clim; 
chl_anom = chl - chl_clim (0 when missing), ESA OCCCI v6; 
ssh_anom = SLA DUACS; 
sst_delta = sst_anom(t-1) previous time step;
sss_delta = sss_anom(t-1) previous time step;
chl_delta = chl_anom(t-1) previous time step;
ssh_delta = ssh_anom(t-1) previous time step;
dfco2_clim = dfco2 8d with RF(pred+lat/lon/doy) <--> NN(pred+lat/lon/doy), see sup for details; 
sst_clim = sst[1990, 2019]; 
sss_clim = CMEMS[1993, 2019] + ESACCI[2011, 2019];
chl_clim = ESA OCCCI v6 [1998, 2019]; 
ssh_clim = DUACS ADT[1993, 2019]; 
mld_clim = SODA 3.4.2 mld[1990, 2019]; 
sst_seas = sst_clim - sst_ltm; 
sss_seas = sss_clim - sss_ltm; 
chl_seas = chl_clim - chl_ltm; 
mld_seas = mld_clim - mld_ltm
